# Let's search if there's any file in the whole filesystem with 'periapical' or 'panoramic' or dataset name
import os
for root, dirs, files in os.walk('/'):
    if 'proc' in root or 'sys' in root or 'dev' in root:
        continue
    for f in files:
        if any(w in f.lower() for w in ['periapical', 'lesion', 'pai', 'annot', 'label', 'coco', 'json']):
            print(os.path.join(root, f))
