# Check python history or recent files
import os, time
files = []
for root, dirs, filenames in os.walk('/app'):
    for fn in filenames:
        fp = os.path.join(root, fn)
        files.append((os.path.getmtime(fp), fp))
files.sort()
for t, fp in files:
    print(time.ctime(t), fp)
